ar["subjects"] = [SUBJ.get(s, s) for s in c["subjects"]]
ar["levels"] = [LEVELS.get(l, l) for l in c["levels"]]
for t in ar["tutors"]:
    name, subject, cred, style, best, badge = TUTORS[t["name"]]
    t.update(name=name, subject=subject, credentials=cred, style=style, bestFor=best, subjects=[SUBJ.get(x, x) for x in t["subjects"]])
    if badge: t["badge"] = badge
for w in ar["wall"]:
    if w["type"] == "stat":
        w["label"] = {"hours of 1:1 tutoring in a single year": "ساعة دروس فردية في عام واحد",
                      "rated Excellent by parents and students": "تقييم ممتاز من أولياء الأمور والطلاب"}.get(w["label"], "المناهج الأمريكية والبريطانية وIB وCBSE/ISC والأسترالية، إضافةً إلى SAT وIMAT وBMAT وUCAT")
        if w["value"].startswith("Years"): w["value"] = "من الصف 4 إلى الجامعة"
    elif w["type"] == "review":
        w["role"] = w["role"].replace("Parent · with SAS for 1.5 years", "وليّ أمر · مع SAS منذ عام ونصف").replace("Year 12 student", "طالب في الصف 12").replace("Parent", "وليّ أمر")
    elif w["type"] == "instagram":
        w["text"] = "تابع نصائح المذاكرة وإنجازات الطلاب على إنستغرام"
names = {"Starter": "باقة البداية", "50 hours": "50 ساعة", "100 hours": "100 ساعة"}
labels = {"Most popular": "الأكثر طلباً", "Best value": "الأفضل قيمة"}
for p in ar["plans"]:
    p["name"] = names[p["name"]]; p["label"] = labels.get(p["label"], p["label"])
ar["planFeatures"] = ["معلّم فردي مختار بعناية", "أي مادة أو منهج أو مدرسة أو جامعة", "ملاحظات بعد كل حصة وتقرير تقدّم شهري", "الساعات لا تنتهي صلاحيتها ويمكن مشاركتها مع العائلة"]
ar["planNote"] = "الأسعار بالدولار الأمريكي وتُحوَّل إلى عملتك المحلية عند الدفع."
ar["faq"] = [{"q": q, "a": a} for q, a in FAQ]
ar["footer"]["subjects"] = [{"label": SUBJ.get(x["label"], x["label"]), "href": "#"} for x in c["footer"]["subjects"]]
ar["footer"]["curricula"] = [x.replace("Australian (HSC, VCE)", "الأسترالي (HSC وVCE)").replace("American", "الأمريكي").replace("University", "الجامعة") for x in c["footer"]["curricula"]]
ar["teachingExperience"] = ["أقل من سنة", "1–3 سنوات", "3–5 سنوات", "5–10 سنوات", "أكثر من 10 سنوات"]
et = ar["levelsBySubject"].pop("Entry test")
et.update(label="أيّ اختبار", placeholder="اختر الاختبار", options=["SAT", "IMAT", "BMAT", "UCAT", "اختبار آخر"],
          goals=["المحاولة الأولى", "تحسين درجتي (إعادة)", "دورة تحضير كاملة", "دورة مكثّفة في اللحظات الأخيرة"])
ar["levelsBySubject"][SUBJ["Entry test"]] = et
ar["goals"] = ["سدّ الفجوات", "تحسين الدرجات", "التحضير للامتحان", "التقدّم على المنهج"]
ar["countries"] = [FORM_COUNTRIES.get(x, x) for x in c["countries"]]
for r in ar["regions"]:
    r["label"] = COUNTRY[r["label"]]
ar["ui"] = {"teaches": "كيف يدرّس {name}", "bestFor": "الأنسب لـ", "flipBack": "اضغط للعودة", "start": "ابدأ الحصة المجانية",
            "hoursTotal": "{hours} ساعة · {total} إجمالاً", "tutor": "معلّم {subject}", "show": "اعرض {name}", "worldwide": "حول العالم"}
(ROOT / "config.ar.json").write_text(json.dumps(ar, ensure_ascii=False, indent=2) + "\n")
print("config.ar.json written")
